import{_ as t,c as o,o as a,a3 as s}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Time Off","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/index.md","filePath":"master/human-resources/time-off/index.md","lastUpdated":1792041590000}'),r={name:"master/human-resources/time-off/index.md"};function n(i,e,l,p,d,h){return a(),o("div",null,e[0]||(e[0]=[s(`<h1 id="time-off" tabindex="-1">Time Off <a class="header-anchor" href="#time-off" aria-label="Permalink to &quot;Time Off&quot;">​</a></h1><p>Time Off lets your people ask for leave and lets managers approve it. It keeps a balance of days for each person. It shows every request on a calendar. You define the kinds of leave, such as <strong>Paid Time Off</strong> or <strong>Sick Time Off</strong>.</p><blockquote><p><strong>In simple words:</strong> Staff ask for days off. Managers say yes or no.</p></blockquote><p>Open the <strong>Time Off</strong> app from the main menu. The top bar shows five menus.</p><h2 id="how-time-off-flows" tabindex="-1">How time off flows <a class="header-anchor" href="#how-time-off-flows" aria-label="Permalink to &quot;How time off flows&quot;">​</a></h2><p>Every request follows the same path. Some steps happen only once, when you set up.</p><ol><li><strong>Set up leave types and holidays.</strong> Create the kinds of leave and list your public holidays.</li><li><strong>Allocate days.</strong> Give each person a number of days, but only for leave types that need it.</li><li><strong>Request time off.</strong> The employee picks a type and dates.</li><li><strong>Approve or refuse.</strong> A manager reviews the request.</li><li><strong>Balance and calendar update.</strong> The days leave the balance and the request appears on the calendar.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leave types and holidays  &gt;  Allocation (if needed)  &gt;  Request</span></span>
<span class="line"><span>        &gt;  Approve or Refuse  &gt;  Balance and calendar</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">Allocation first</p><p>An allocation is a number of days given to one person. Aureus checks the person&#39;s approved days when you save a request. With no approved allocation for that type, the request is denied. This applies to every seeded leave type, including <strong>Sick Time Off</strong>. See <a href="./allocations/">Allocations</a>.</p></div><h2 id="who-approves" tabindex="-1">Who approves <a class="header-anchor" href="#who-approves" aria-label="Permalink to &quot;Who approves&quot;">​</a></h2><p>Two settings name the approvers.</p><ul><li><strong>Employee&#39;s Approver:</strong> the user named in the <strong>Time Off</strong> field on the employee form, under <strong>Work Information</strong>.</li><li><strong>Approval:</strong> a setting on each leave type. It records whether the Employee&#39;s Approver, a Time Off Officer, both or nobody should approve. See <a href="./setup/time-off-types.html">Leave types</a>.</li></ul><p>On <code>Time Off → Management → Time off</code>, the <strong>Approve</strong> button shows on every request that is not yet approved. One click sets the status to <strong>Approved</strong>.</p><h2 id="the-five-menus" tabindex="-1">The five menus <a class="header-anchor" href="#the-five-menus" aria-label="Permalink to &quot;The five menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>What it holds</th><th>Sidebar labels</th></tr></thead><tbody><tr><td><strong>My Time</strong></td><td>Your balance cards, your calendar, the Holidays window and your own lists</td><td><strong>Dashboard</strong>, <strong>My Time off</strong>, <strong>My Allocation</strong></td></tr><tr><td><strong>Overview</strong></td><td>A full year calendar with requests of all employees</td><td>None</td></tr><tr><td><strong>Management</strong></td><td>The lists where managers approve and refuse requests and allocations</td><td><strong>Time off</strong>, <strong>Allocation</strong></td></tr><tr><td><strong>Reporting</strong></td><td>A list of requests grouped by employee</td><td><strong>By Employees</strong></td></tr><tr><td><strong>Configuration</strong></td><td>Leave types, public holidays and mandatory days</td><td><strong>Leave Types</strong>, <strong>Public Holidays</strong>, <strong>Mandatory Holidays</strong></td></tr></tbody></table><p>The menu <strong>Mandatory Holidays</strong> opens a page titled <strong>Mandatory Days</strong>. This guide calls them mandatory days.</p><h2 id="leave-types-that-come-with-the-app" tabindex="-1">Leave types that come with the app <a class="header-anchor" href="#leave-types-that-come-with-the-app" aria-label="Permalink to &quot;Leave types that come with the app&quot;">​</a></h2><p>Seven leave types are ready to use.</p><ul><li><strong>Paid Time Off:</strong> <strong>Requires Allocation</strong> is <strong>Yes</strong>.</li><li><strong>Sick Time Off:</strong> <strong>Requires Allocation</strong> is <strong>No Limit</strong>.</li><li><strong>Compensatory Days:</strong> <strong>No Limit</strong>.</li><li><strong>Unpaid:</strong> <strong>No Limit</strong>.</li><li><strong>Parental Leaves:</strong> <strong>Yes</strong>. Employees can ask for extra days.</li><li><strong>Training Time Off:</strong> <strong>Yes</strong>.</li><li><strong>Extra Hours:</strong> <strong>No Limit</strong>.</li></ul><p>Sample data may also hold allocations, for example 20 days of <strong>Paid Time Off</strong> for 2026. See <a href="./setup/time-off-types.html">Leave types</a> for every setting.</p><h2 id="relation-to-employees" tabindex="-1">Relation to Employees <a class="header-anchor" href="#relation-to-employees" aria-label="Permalink to &quot;Relation to Employees&quot;">​</a></h2><p>Time Off works on employees. A person needs an employee record before they can request leave. The <strong>Time Off</strong> approver field on the employee form, under <strong>Work Information</strong>, names the user who approves their leave. See <a href="./../employees/employees/add-employee.html">Add an employee</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>New to Time Off? Follow <a href="./get-started/first-steps.html">First steps</a>.</li><li>Learn the settings in <a href="./setup/">Setup</a>.</li><li>Learn allocations in <a href="./allocations/">Allocations</a>.</li><li>Learn requests in <a href="./requests/">Requests</a>.</li><li>See the grouped list in <a href="./reporting/by-employees.html">By Employees</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./requests/">Time off requests</a></li><li><a href="./allocations/">Allocations</a></li><li><a href="./../employees/">Employees overview</a></li></ul>`,26)]))}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
